const VERSION='picpac-shell-v13';
const STUDIO=['./motion.js','./album-render.css','./album-design.js','./ai-workspace.js','./document-studio.js','./document-studio-profile.js','./account-plans.js','./theme.js','./dark.css'];
const CORE=['./','./index.html','./styles.css','./document-scan.css','./ai-glass.css','./ai-album.js','./assets/picpac-ai-robot.png','./assets/picpac-ai-face.png','./app.js','./data.js','./icons.js','./store.js','./project-rules.js','./portrait.js','./portrait-processing.js','./document-quality.js','./document-validator.js','./ai-client.js','./ai-config.json','./manifest.webmanifest','./assets/logo.svg','./assets/picpac-cat.png','./assets/futura-pt-400.woff2','./assets/futura-pt-500.woff2','./assets/book-lite.png','./assets/book-classic.png','./assets/book-premium.png','./assets/prints.jpg','./assets/prints-detail.webp','./assets/template-family.webp','./assets/template-travel.webp','./assets/template-baby.webp','./assets/family-winter.jpg'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(VERSION).then(cache=>cache.addAll([...CORE,...STUDIO])).then(()=>self.skipWaiting()));});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key.startsWith('picpac-shell-')&&key!==VERSION).map(key=>caches.delete(key)))).then(()=>self.clients.claim()));});
self.addEventListener('fetch',event=>{if(new URL(event.request.url).pathname.startsWith('/api/'))return;if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;event.respondWith(fetch(event.request).then(response=>{if(response.ok){const copy=response.clone();caches.open(VERSION).then(cache=>cache.put(event.request,copy));}return response;}).catch(()=>caches.match(event.request).then(cached=>cached||(event.request.mode==='navigate'?caches.match('./index.html'):Response.error()))));});
